<script>import {onMount} from 'svelte';import {events,errors,loadResource} from '../state.js';import {date,sessionGet,sessionSet,download,csv} from '../lib.js';import Icon from '../components/Icon.svelte';let search=sessionGet('events.search',''),level=sessionGet('events.level','all'),expanded=sessionGet('events.expanded',null);$: sessionSet('events.search',search);$: sessionSet('events.level',level);$: sessionSet('events.expanded',expanded);$: shown=$events.filter(e=>(level==='all'||e.severity===level)&&(e.message+' '+e.node+' '+e.type).toLowerCase().includes(search.toLowerCase()));onMount(()=>loadResource('events'));</script>
<section class="panel"><div class="toolbar"><label class="search"><Icon name="search" size={16}/><input bind:value={search} placeholder="イベントを検索" aria-label="イベント検索"/></label><select bind:value={level} aria-label="重要度"><option value="all">すべての重要度</option><option value="critical">異常</option><option value="warning">注意</option><option value="info">情報</option></select><button onclick={()=>loadResource('events',true)}><Icon name="refresh" size={14}/>履歴を更新</button><button onclick={()=>download('scyllascope-events.csv',csv(shown,['time','severity','type','node','message']),'text/csv;charset=utf-8')}><Icon name="download" size={14}/>CSV</button><span class="quiet count">{shown.length} 件（最大500件）</span></div>{#if $errors.events}<p class="notice warning">{$errors.events}</p>{/if}<div class="table-scroll"><table class="events-table"><thead><tr><th>時刻</th><th>種別</th><th>内容</th></tr></thead><tbody>{#each shown as e (e.id)}<tr><td class="mono nowrap">{date(e.time)}</td><td><span class="dot {e.severity}"></span><span class="quiet">{e.type}</span></td><td><button class="event-expand" aria-expanded={expanded===e.id} onclick={()=>expanded=expanded===e.id?null:e.id}>{e.message}</button>{#if expanded===e.id}<div class="event-detail"><span>ノード: {e.node||'—'}</span><span>ID: {e.id}</span><span>重要度: {e.severity}</span></div>{/if}</td></tr>{:else}<tr><td colspan="3" class="empty-row">該当するイベントはありません</td></tr>{/each}</tbody></table></div></section>
